import{_ as t,H as a,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"07 | 自己动手，搭建HTTP实验环境","description":"","frontmatter":{},"headers":[{"level":2,"title":"“破冰篇”回顾","slug":"破冰篇-回顾","link":"#破冰篇-回顾","children":[]},{"level":2,"title":"软件介绍","slug":"软件介绍","link":"#软件介绍","children":[]},{"level":2,"title":"安装过程","slug":"安装过程","link":"#安装过程","children":[]},{"level":2,"title":"测试验证","slug":"测试验证","link":"#测试验证","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"课下作业","slug":"课下作业","link":"#课下作业","children":[]}],"relativePath":"透视HTTP协议/07-自己动手，搭建HTTP实验环境.md","filePath":"透视HTTP协议/07-自己动手，搭建HTTP实验环境.md","lastUpdated":1779822553000}'),n={name:"透视HTTP协议/07-自己动手，搭建HTTP实验环境.md"};function r(o,e,p,l,h,g){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="_07-自己动手-搭建http实验环境" tabindex="-1">07 | 自己动手，搭建HTTP实验环境 <a class="header-anchor" href="#_07-自己动手-搭建http实验环境" aria-label="Permalink to &quot;07 | 自己动手，搭建HTTP实验环境&quot;">​</a></h1><p>这一讲是“破冰篇”的最后一讲，我会先简单地回顾一下之前的内容，然后在Windows系统上实际操作，用几个应用软件搭建出一个“最小化”的HTTP实验环境，方便后续的“基础篇”“进阶篇”“安全篇”的学习。</p><h2 id="破冰篇-回顾" tabindex="-1">“破冰篇”回顾 <a class="header-anchor" href="#破冰篇-回顾" aria-label="Permalink to &quot;“破冰篇”回顾&quot;">​</a></h2><p>HTTP协议诞生于30年前，设计之初的目的是用来传输纯文本数据。但由于形式灵活，搭配URI、HTML等技术能够把互联网上的资源都联系起来，构成一个复杂的超文本系统，让人们自由地获取信息，所以得到了迅猛发展。</p><p>HTTP有多个版本，目前应用的最广泛的是HTTP/1.1，它几乎可以说是整个互联网的基石。但HTTP/1.1的性能难以满足如今的高流量网站，于是又出现了HTTP/2和HTTP/3。不过这两个新版本的协议还没有完全推广开。在可预见的将来，HTTP/1.1还会继续存在下去。</p><p>HTTP翻译成中文是“超文本传输协议”，是一个应用层的协议，通常基于TCP/IP，能够在网络的任意两点之间传输文字、图片、音频、视频等数据。</p><p>HTTP协议中的两个端点称为 <strong>请求方</strong> 和 <strong>应答方</strong>。请求方通常就是Web浏览器，也叫user agent，应答方是Web服务器，存储着网络上的大部分静态或动态的资源。</p><p>在浏览器和服务器之间还有一些“中间人”的角色，如CDN、网关、代理等，它们也同样遵守HTTP协议，可以帮助用户更快速、更安全地获取资源。</p><p>HTTP协议不是一个孤立的协议，需要下层很多其他协议的配合。最基本的是TCP/IP，实现寻址、路由和可靠的数据传输，还有DNS协议实现对互联网上主机的定位查找。</p><p>对HTTP更准确的称呼是“ <strong>HTTP over TCP/IP</strong>”，而另一个“ <strong>HTTP over SSL/TLS</strong>”就是增加了安全功能的HTTPS。</p><h2 id="软件介绍" tabindex="-1">软件介绍 <a class="header-anchor" href="#软件介绍" aria-label="Permalink to &quot;软件介绍&quot;">​</a></h2><p>常言道“实践出真知”，又有俗语“光说不练是假把式”。要研究HTTP协议，最好有一个实际可操作、可验证的环境，通过实际的数据、现象来学习，肯定要比单纯的“动嘴皮子”效果要好的多。</p><p>现成的环境当然有，只要能用浏览器上网，就会有HTTP协议，就可以进行实验。但现实的网络环境又太复杂了，有很多无关的干扰因素，这些“噪音”会“淹没”真正有用的信息。</p><p>所以，我给你的建议是：搭建一个“ <strong>最小化</strong>”的环境，在这个环境里仅有HTTP协议的两个端点：请求方和应答方，去除一切多余的环节，从而可以抓住重点，快速掌握HTTP的本质。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/85cadf90dc96cf413afaf8668689ef0b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/85cadf90dc96cf413afaf8668689ef0b.png" alt=""></a></p><p>简单说一下这个“最小化”环境用到的应用软件：</p><ul><li>Wireshark</li><li>Chrome/Firefox</li><li>Telnet</li><li>OpenResty</li></ul><p><strong>Wireshark</strong> 是著名的网络抓包工具，能够截获在TCP/IP协议栈中传输的所有流量，并按协议类型、地址、端口等任意过滤，功能非常强大，是学习网络协议的必备工具。</p><p>它就像是网络世界里的一台“高速摄像机”，把只在一瞬间发生的网络传输过程如实地“拍摄”下来，事后再“慢速回放”，让我们能够静下心来仔细地分析那一瞬到底发生了什么。</p><p><strong>Chrome</strong> 是Google开发的浏览器，是目前的主流浏览器之一。它不仅上网方便，也是一个很好的调试器，对HTTP/1.1、HTTPS、HTTP/2、QUIC等的协议都支持得非常好，用F12打开“开发者工具”还可以非常详细地观测HTTP传输全过程的各种数据。</p><p>如果你更习惯使用 <strong>Firefox</strong>，那也没问题，其实它和Chrome功能上都差不太多，选择自己喜欢的就好。</p><p>与Wireshark不同，Chrome和Firefox属于“事后诸葛亮”，不能观测HTTP传输的过程，只能看到结果。</p><p><strong>Telnet</strong> 是一个经典的虚拟终端，基于TCP协议远程登录主机，我们可以使用它来模拟浏览器的行为，连接服务器后手动发送HTTP请求，把浏览器的干扰也彻底排除，能够从最原始的层面去研究HTTP协议。</p><p><strong>OpenResty</strong> 你可能比较陌生，它是基于Nginx的一个“强化包”，里面除了Nginx还有一大堆有用的功能模块，不仅支持HTTP/HTTPS，还特别集成了脚本语言Lua简化Nginx二次开发，方便快速地搭建动态网关，更能够当成应用容器来编写业务逻辑。</p><p>选择OpenResty而不直接用Nginx的原因是它相当于Nginx的“超集”，功能更丰富，安装部署更方便。我也会用Lua编写一些服务端脚本，实现简单的Web服务器响应逻辑，方便实验。</p><h2 id="安装过程" tabindex="-1">安装过程 <a class="header-anchor" href="#安装过程" aria-label="Permalink to &quot;安装过程&quot;">​</a></h2><p>这个“最小化”环境的安装过程也比较简单，大约只需要你半个小时不到的时间就能搭建完成。</p><p>我在GitHub上为本专栏开了一个项目： <a href="https://github.com/chronolaw/http_study.git" target="_blank" rel="noreferrer">http_study</a>，可以直接用“git clone”下载，或者去Release页面，下载打好的 <a href="https://github.com/chronolaw/http_study/releases" target="_blank" rel="noreferrer">压缩包</a>。</p><p>我使用的操作环境是Windows 10，如果你用的是Mac或者Linux，可以用VirtualBox等虚拟机软件安装一个Windows虚拟机，再在里面操作（或者可以到“答疑篇”的 <a href="https://time.geekbang.org/column/article/146833" target="_blank" rel="noreferrer">Linux/Mac实验环境搭建</a> 中查看搭建方法）。</p><p>首先你要获取 <strong>最新</strong> 的http_study项目源码，假设clone或解压的目录是“D:\\http_study”，操作完成后大概是下图这个样子。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/862511b8ef87f78218631d832927bcee.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/862511b8ef87f78218631d832927bcee.png" alt=""></a></p><p>Chrome和WireShark的安装比较简单，一路按“下一步”就可以了。版本方面使用最新的就好，我的版本可能不是最新的，Chrome是73，WireShark是3.0.0。</p><p>Windows 10自带Telnet，不需要安装，但默认是不启用的，需要你稍微设置一下。</p><p>打开Windows的设置窗口，搜索“Telnet”，就会找到“启用或关闭Windows功能”，在这个窗口里找到“Telnet客户端”，打上对钩就可以了，可以参考截图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/1af035861c4fd33cb42005eaa1f5f247.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/1af035861c4fd33cb42005eaa1f5f247.png" alt=""></a></p><p>接下来我们要安装OpenResty，去它的 <a href="http://openresty.org" target="_blank" rel="noreferrer">官网</a>，点击左边栏的“Download”，进入下载页面，下载适合你系统的版本（这里我下载的是64位的1.15.8.1，包的名字是“openresty-1.15.8.1-win64.zip”）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/ee7016fecd79919de550677af32f740a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/ee7016fecd79919de550677af32f740a.png" alt=""></a></p><p>然后要注意，你必须把OpenResty的压缩包解压到刚才的“D:\\http_study”目录里，并改名为“openresty”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/5acb89c96041f91bbc747b7e909fd4b5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/5acb89c96041f91bbc747b7e909fd4b5.png" alt=""></a></p><p>安装工作马上就要完成了，为了能够让浏览器能够使用DNS域名访问我们的实验环境，还要改一下本机的hosts文件，位置在“C:\\WINDOWS\\system32\\drivers\\etc”，在里面添加三行本机IP地址到测试域名的映射，你也可以参考GitHub项目里的hosts文件，这就相当于在一台物理实机上“托管”了三个虚拟主机。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>127.0.0.1       www.chrono.com</span></span>
<span class="line"><span>127.0.0.1       www.metroid.net</span></span>
<span class="line"><span>127.0.0.1       origin.io</span></span></code></pre></div><p>注意修改hosts文件需要管理员权限，直接用记事本编辑是不行的，可以切换管理员身份，或者改用其他高级编辑器，比如Notepad++，而且改之前最好做个备份。</p><p>到这里，我们的安装工作就完成了！之后你就可以用Wireshark、Chrome、Telnet在这个环境里随意“折腾”，弄坏了也不要紧，只要把目录删除，再来一遍操作就能复原。</p><h2 id="测试验证" tabindex="-1">测试验证 <a class="header-anchor" href="#测试验证" aria-label="Permalink to &quot;测试验证&quot;">​</a></h2><p>实验环境搭建完了，但还需要把它运行起来，做一个简单的测试验证，看是否运转正常。</p><p>首先我们要启动Web服务器，也就是OpenResty。</p><p>在http_study的“www”目录下有四个批处理文件，分别是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/e5d35bb94c46bfaaf8ce5c143b2bb2da.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/e5d35bb94c46bfaaf8ce5c143b2bb2da.png" alt=""></a></p><ul><li>start：启动OpenResty服务器；</li><li>stop：停止OpenResty服务器；</li><li>reload：重启OpenResty服务器；</li><li>list：列出已经启动的OpenResty服务器进程。</li></ul><p>使用鼠标双击“start”批处理文件，就会启动OpenResty服务器在后台运行，这个过程可能会有Windows防火墙的警告，选择“允许”即可。</p><p>运行后，鼠标双击“list”可以查看OpenResty是否已经正常启动，应该会有两个nginx.exe的后台进程，大概是下图的样子。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/dba34b8a38e98bef92289315db29ee1d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/dba34b8a38e98bef92289315db29ee1d.png" alt=""></a></p><p>有了Web服务器后，接下来我们要运行Wireshark，开始抓包。</p><p>因为我们的实验环境运行在本机的127.0.0.1上，也就是loopback“环回”地址。所以，在Wireshark里要选择“Npcap loopback Adapter”，过滤器选择“HTTP TCP port(80)”，即只抓取HTTP相关的数据包。鼠标双击开始界面里的“Npcap loopback Adapter”即可开始抓取本机上的网络数据。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/128d8a5ed9cdd666dbfa4e17fd39afc4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/128d8a5ed9cdd666dbfa4e17fd39afc4.png" alt=""></a></p><p>然后我们打开Chrome，在地址栏输入“ <code>http://localhost</code>”，访问刚才启动的OpenResty服务器，就会看到一个简单的欢迎界面，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/d7f12d4d480d7100cd9804d2b16b8a88.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/d7f12d4d480d7100cd9804d2b16b8a88.png" alt=""></a></p><p>这时再回头去看Wireshark，应该会显示已经抓到了一些数据，就可以用鼠标点击工具栏里的“停止捕获”按钮告诉Wireshark“到此为止”，不再继续抓包。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/f7d05a3939d81742f18d2da7a1883179.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/f7d05a3939d81742f18d2da7a1883179.png" alt=""></a></p><p>至于这些数据是什么，表示什么含义，我会在下一讲再详细介绍。</p><p>如果你能够在自己的电脑上走到这一步，就说明“最小化”的实验环境已经搭建成功了，不要忘了实验结束后运行批处理“stop”停止OpenResty服务器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这次我们学习了如何在自己的电脑上搭建HTTP实验环境，在这里简单小结一下今天的内容。</p><ol><li>现实的网络环境太复杂，有很多干扰因素，搭建“最小化”的环境可以快速抓住重点，掌握HTTP的本质；</li><li>我们选择Wireshark作为抓包工具，捕获在TCP/IP协议栈中传输的所有流量；</li><li>我们选择Chrome或Firefox浏览器作为HTTP协议中的user agent；</li><li>我们选择OpenResty作为Web服务器，它是一个Nginx的“强化包”，功能非常丰富；</li><li>Telnet是一个命令行工具，可用来登录主机模拟浏览器操作；</li><li>在GitHub上可以下载到本专栏的专用项目源码，只要把OpenResty解压到里面即可完成实验环境的搭建。</li></ol><h2 id="课下作业" tabindex="-1">课下作业 <a class="header-anchor" href="#课下作业" aria-label="Permalink to &quot;课下作业&quot;">​</a></h2><p>1.按照今天所学的，在你自己的电脑上搭建出这个HTTP实验环境并测试验证。</p><p>2.由于篇幅所限，我无法详细介绍Wireshark，你有时间可以再上网搜索Wireshark相关的资料，了解更多的用法。</p><p>欢迎你把自己的学习体会写在留言区，与我和其他同学一起讨论。如果你觉得有所收获，也欢迎把文章分享给你的朋友。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/03727c2a64cbc628ec18cf39a6a526dd.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/03727c2a64cbc628ec18cf39a6a526dd.png" alt="unpreview"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/56d766fc04654a31536f554b8bde7b63.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%80%8F%E8%A7%86HTTP%E5%8D%8F%E8%AE%AE/images/100124/56d766fc04654a31536f554b8bde7b63.jpg" alt="unpreview"></a></p>`,70)])])}const T=t(n,[["render",r]]);export{b as __pageData,T as default};
